 "content": "def transform(grid):
    """Complete the masked tile band and mark each tile at its lattice coordinate."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    cells3 = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 3]
    if not cells3:
        return g

    r0, r1 = min(r for r, _ in cells3), max(r for r, _ in cells3)
    c0, c1 = min(c for _, c in cells3), max(c for _, c in cells3)
    band_h, band_w = r1 - r0 + 1, c1 - c0 + 1
    horizontal = band_h >= band_w
    size = band_h if horizontal else band_w
    stride = size + 1

    # The 3-colored region is a whole missing tile row or column.
    if horizontal:
        missing_index = r0 // stride
    else:
        missing_index = c0 // stride

    nrows = (h + 1) // stride
    ncols = (w + 1) // stride
    present = [[False] * ncols for _ in range(nrows)]
    for tr in range(nrows):
        for tc in range(ncols):
            sr, sc = tr * stride, tc * stride
            if sr + size <= h and sc + size <= w:
                present[tr][tc] = any(g[r][c] == 2
                                      for r in range(sr, sr + size)
                                      for c in range(sc, sc + size))

    # Infer which tiles belong in the masked band from the visible lattice.
    if horizontal:
        rows = [tr for tr in range(nrows) if tr != missing_index]
        common = set(range(ncols))
        for tr in rows:
            common &= {tc for tc in range(ncols) if present[tr][tc]}
        targets = [(missing_index, tc) for tc in sorted(common)]
    else:
        # In the vertical examples the hidden column is the first visible
        # column's tile set minus the next visible column's tile set.
        left = {tr for tr in range(nrows) if present[tr][0]}
        next_col = {tr for tr in range(nrows) if ncols > 1 and present[tr][1]}
        targets = [(tr, missing_index) for tr in sorted(left - next_col)]

    # Clear the mask before reconstructing its inferred tiles.
    for r, c in cells3:
        g[r][c] = 0

    # All tile instances share the same motif; use the first existing one.
    source = next(((tr, tc) for tr in range(nrows) for tc in range(ncols)
                   if present[tr][tc]), None)
    if source is not None:
        sr, sc = source[0] * stride, source[1] * stride
        motif = [g[sr + dr][sc + dc] for dr in range(size) for dc in range(size)]
        for tr, tc in targets:
            rr, cc = tr * stride, tc * stride
            for dr in range(size):
                for dc in range(size):
                    g[rr + dr][cc + dc] = motif[dr * size + dc]

    # Mark the cell whose local coordinates equal the tile's lattice position.
    for tr in range(nrows):
        for tc in range(ncols):
            if present[tr][tc] or (tr, tc) in targets:
                rr, cc = tr * stride + tr, tc * stride + tc
                if rr < h and cc < w and g[rr][cc] == 2:
                    g[rr][cc] = 8
    return g


