    stride = size + 1
    nr, nc = (h+1)//stride, (w+1)//stride
    mr = r0//stride if horizontal else None
    mc = c0//stride if not horizontal else None

    # Every tile is a copy of the same binary motif. Find an unmasked tile.
    source = None
    for tr in range(nr):
        for tc in range(nc):
            if horizontal and tr == mr or (not horizontal and tc == mc):
                continue
            sr, sc = tr*stride, tc*stride
            if sr+size <= h and sc+size <= w and any(
                    g[r][c] == 2 for r in range(sr, sr+size)
                    for c in range(sc, sc+size)):
                source = (sr, sc)
                break
        if source:
            break
    if source is None:
        return g
    sr, sc = source
    motif = [[g[sr+dr][sc+dc] for dc in range(size)] for dr in range(size)]

    # Tile (tr,tc) exists exactly when motif[tr][tc] is occupied.
    for tr in range(nr):
        for tc in range(nc):
            if tr >= size or tc >= size or motif[tr][tc] != 2:
