            # The marker is the motif's tile-coordinate cell, recolored 8.
            if g[rr+tr][cc+tc] == 2:
                g[rr+tr][cc+tc] = 8

    # The colored mask is background in the output.
    for r, c in colored:
        g[r][c] = 0
    return g

